export const PREGEN_TEXT = {"README.md":"# Chunk Pregen v1.2.0 (Minecraft Bedrock behavior pack)\n\nGenerates every chunk in a region so you don't have to fly it.\n\n## Which file\n- **chunk-pregen-v1.2.0.mcpack**: Bedrock **26.10 or newer**. Area mode uses the Script API's own\n  ticking areas, a per-pack chunk budget that doesn't touch the world's 10 /tickingarea slots.\n- **chunk-pregen-v1.2.0-legacy.mcpack**: Bedrock 1.21.90 to 26.0x. Area mode uses the /tickingarea\n  command (10 slots x 100 chunks per world).\nInstall one, not both. If the regular pack does nothing at all (not even /scriptevent pregen:help),\nyour game is older than 26.10: use the legacy one.\n\nEnable it in the world's Behavior Packs and turn **Cheats on** (needed for /scriptevent).\n\n## Why chunks are marked\nBedrock only writes a chunk to disk if it changed since it was generated; an untouched\nchunk is dropped and regenerated from the seed on the next visit. Loading chunks alone\ntherefore leaves them out of the save file, so external tools (world maps, Polis) don't\nsee them. While each chunk is loaded, the pack flips one block at the top of the world\nand immediately puts it back (air at the build limit via structure_void; the Nether's\nbedrock roof via barrier). The chunk counts as modified and is saved; the world is\nunchanged. `mark=off` skips this.\n\n## Modes\n**area**: force-loads the region batch by batch. Fastest; you can stand anywhere.\n**walk**: teleports you in a snake path (spectator by default) and waits for chunks at each stop.\nSlower, but a map in your main hand or offhand fills in. You're returned to your start\nposition and game mode afterwards.\n\n## Commands\n```\n/scriptevent pregen:menu\n/scriptevent pregen:area -2000 -2000 2000 2000\n/scriptevent pregen:radius area 1500\n/scriptevent pregen:walk ~-1000 ~-1000 ~1000 ~1000 step=64\n/scriptevent pregen:status | pause | resume | stop | diag | help\n```\nBoth modes: `mark=on|off` (default on).\nArea options: `dim=` `budget=` (max chunks loaded per batch, default 1000; capped by the pack budget)\n`timeout=` (seconds per batch, default 60) `tile=`\nWalk options: `step=` (default 128) `y=` `gm=spectator|creative` `dwell=` `maxdwell=`\n\n`pregen:diag` shows which backend is active, the pack's chunk budget, and tries a 1-chunk test area,\nprinting the exact error if it fails.\n\nJobs are saved in the world. Closing the world pauses; `pregen:resume` continues.\n","manifest.json":"{\n  \"format_version\": 2,\n  \"header\": {\n    \"name\": \"Chunk Pregen v1.2.0\",\n    \"description\": \"Pre-generate chunks for a region (Bedrock 26.10+). Area mode uses the pack's own ticking areas; walk mode fills held maps. /scriptevent pregen:help\",\n    \"uuid\": \"501f92cb-2b82-41ea-b84f-ea99dfec3db9\",\n    \"version\": [\n      1,\n      2,\n      0\n    ],\n    \"min_engine_version\": [\n      1,\n      21,\n      90\n    ]\n  },\n  \"modules\": [\n    {\n      \"type\": \"data\",\n      \"uuid\": \"ff887ddd-ef04-4df7-b6c8-b43c3d4c0512\",\n      \"version\": [\n        1,\n        2,\n        0\n      ]\n    },\n    {\n      \"type\": \"script\",\n      \"language\": \"javascript\",\n      \"uuid\": \"cb1bbeb1-7bf6-4f01-804f-bae49475e9e7\",\n      \"version\": [\n        1,\n        2,\n        0\n      ],\n      \"entry\": \"scripts/main.js\"\n    }\n  ],\n  \"dependencies\": [\n    {\n      \"module_name\": \"@minecraft/server\",\n      \"version\": \"2.6.0\"\n    },\n    {\n      \"module_name\": \"@minecraft/server-ui\",\n      \"version\": \"2.0.0\"\n    }\n  ]\n}","manifest.legacy.json":"{\n  \"format_version\": 2,\n  \"header\": {\n    \"name\": \"Chunk Pregen v1.2.0 (legacy)\",\n    \"description\": \"For Bedrock 1.21.90 to 26.0x. Area mode uses the /tickingarea command (10 world slots). /scriptevent pregen:help\",\n    \"uuid\": \"5cffe886-c863-4724-80e5-c38cb5eb557d\",\n    \"version\": [\n      1,\n      2,\n      0\n    ],\n    \"min_engine_version\": [\n      1,\n      21,\n      90\n    ]\n  },\n  \"modules\": [\n    {\n      \"type\": \"data\",\n      \"uuid\": \"b83bc4fe-650e-48ba-9e2a-ae3ea7b4d149\",\n      \"version\": [\n        1,\n        2,\n        0\n      ]\n    },\n    {\n      \"type\": \"script\",\n      \"language\": \"javascript\",\n      \"uuid\": \"93370369-c1da-49e5-ad04-484fffef8a64\",\n      \"version\": [\n        1,\n        2,\n        0\n      ],\n      \"entry\": \"scripts/main.js\"\n    }\n  ],\n  \"dependencies\": [\n    {\n      \"module_name\": \"@minecraft/server\",\n      \"version\": \"2.0.0\"\n    },\n    {\n      \"module_name\": \"@minecraft/server-ui\",\n      \"version\": \"2.0.0\"\n    }\n  ]\n}","scripts/areaMode.js":"// AREA mode: force-load the region in batches of ticking areas.\n// Backend 1 (preferred): world.tickingAreaManager (@minecraft/server 2.6.0+, Bedrock 26.10+).\n//   Uses a per-pack chunk budget, independent of the 10-area /tickingarea limit.\n// Backend 2 (legacy): the /tickingarea command (10 areas x 100 chunks per world).\nimport { world } from \"@minecraft/server\";\nimport { chunkRect, tileGrid, tileAt, tileChunkCount } from \"./geometry.js\";\nimport { isLoadedAt, probeY } from \"./chunks.js\";\nimport { saveJob } from \"./store.js\";\nimport { markRect, markY } from \"./mark.js\";\n\nexport const AREA_PREFIX = \"pregen_\";\nexport const CMD_MAX_AREAS = 10;\nexport const CMD_MAX_TILE = 10; // 10x10 = the command's 100-chunk cap\n\nexport function errText(e) {\n  if (e === undefined || e === null) return \"unknown error\";\n  const msg = e.message ?? String(e);\n  return e.reason ? `${msg} (${e.reason})` : msg;\n}\n\nexport function getManager() {\n  try { return world.tickingAreaManager ?? null; } catch { return null; }\n}\n\nexport function backendName() {\n  return getManager() ? \"pack ticking areas (Script API)\" : \"/tickingarea command\";\n}\n\nclass ManagerBackend {\n  constructor(dim, tam) {\n    this.dim = dim; this.tam = tam; this.gen = 0; this.state = new Map();\n    this.label = \"the Script API ticking-area manager\";\n  }\n  maxChunks() {\n    try { const m = this.tam.maxChunkCount; return Number.isFinite(m) && m > 0 ? m : Infinity; } catch { return Infinity; }\n  }\n  maxAreas() { return Infinity; }\n  maxTileSide() { return 255; }\n  beginBatch() { this.gen++; this.state = new Map(); }\n  add(k, from, to) {\n    const opts = { dimension: this.dim, from, to };\n    try {\n      if (!this.tam.hasCapacity(opts)) {\n        let used = \"?\", max = \"?\";\n        try { used = this.tam.chunkCount; max = this.tam.maxChunkCount; } catch { /* ignore */ }\n        return `no room in this pack's ticking-chunk budget (${used}/${max} in use)`;\n      }\n    } catch (e) { return errText(e); }\n    const g = this.gen;\n    try {\n      const p = this.tam.createTickingArea(AREA_PREFIX + k, opts);\n      this.state.set(k, \"pending\");\n      if (p && typeof p.then === \"function\") {\n        p.then(\n          () => { if (g === this.gen) this.state.set(k, \"loaded\"); },\n          (e) => { if (g === this.gen) this.state.set(k, \"error\"); this.lastError = errText(e); });\n      }\n    } catch (e) { return errText(e); }\n    return null;\n  }\n  loaded(k) { return this.state.get(k) === \"loaded\"; }\n  remove(k) { try { this.tam.removeTickingArea(AREA_PREFIX + k); } catch { /* not present */ } }\n  clear() { this.gen++; this.state = new Map(); try { this.tam.removeAllTickingAreas(); } catch { /* ignore */ } }\n}\n\nclass CommandBackend {\n  constructor(dim) { this.dim = dim; this.label = \"/tickingarea\"; }\n  maxChunks() { return CMD_MAX_AREAS * CMD_MAX_TILE * CMD_MAX_TILE; }\n  maxAreas() { return CMD_MAX_AREAS; }\n  maxTileSide() { return CMD_MAX_TILE; }\n  beginBatch() {}\n  add(k, from, to) {\n    const cmd = `tickingarea add ${from.x} ${from.y} ${from.z} ${to.x} ${to.y} ${to.z} ${AREA_PREFIX}${k}`;\n    try {\n      const r = this.dim.runCommand(cmd);\n      if ((r?.successCount ?? 0) > 0) return null;\n      return `\"/${cmd}\" reported 0 successes. Usually all 10 world ticking-area slots are taken; ` +\n        `check /tickingarea list all-dimensions`;\n    } catch (e) {\n      return `\"/${cmd}\" failed: ${errText(e)}`;\n    }\n  }\n  loaded() { return false; } // command gives no load signal; chunk probes decide\n  remove(k) { try { this.dim.runCommand(`tickingarea remove ${AREA_PREFIX}${k}`); } catch { /* not present */ } }\n  clear() { for (let k = 0; k < CMD_MAX_AREAS; k++) this.remove(k); }\n}\n\nexport function makeBackend(dim) {\n  const tam = getManager();\n  return tam ? new ManagerBackend(dim, tam) : new CommandBackend(dim);\n}\n\nexport function clearAreas(dim) { makeBackend(dim).clear(); }\nexport function finalizeArea(job) { clearAreas(world.getDimension(job.dim)); }\n\nexport class AreaRunner {\n  constructor(job) {\n    this.job = job;\n    this.dim = world.getDimension(job.dim);\n    this.backend = makeBackend(this.dim);\n    this.c = chunkRect(job.rect);\n    this.y = probeY(this.dim);\n    this.markY = markY(this.dim);\n    const maxC = this.backend.maxChunks();\n    this.fitSide = Math.max(1, Math.min(job.opts.tile, this.backend.maxTileSide(), Math.floor(Math.sqrt(maxC))));\n    this.budget = Math.min(job.opts.budget ?? 1000, maxC);\n    this.error = null;\n    this.state = \"place\";\n  }\n\n  start() {\n    const j = this.job;\n    this.backend.clear();\n    // Tile index is only meaningful for one tile size; keep it unless the backend can't fit it.\n    if (!j.tileSide) j.tileSide = this.fitSide;\n    else if (j.tileSide > this.fitSide) {\n      j.tileSide = this.fitSide; j.index = 0; j.done = 0; j.skipped = 0;\n      this.notice = \"Tile size changed for this backend; progress restarted (already-generated chunks load fast).\";\n    }\n    this.tile = j.tileSide;\n    this.grid = tileGrid(this.c, this.tile);\n    saveJob(j);\n    return null;\n  }\n\n  tick(now) {\n    const j = this.job;\n\n    if (this.state === \"place\") {\n      if (j.index >= this.grid.total) return \"done\";\n      this.backend.beginBatch();\n      this.tiles = [];\n      this.batchChunks = 0;\n      let firstErr = null;\n      for (let k = 0; j.index + k < this.grid.total && k < this.backend.maxAreas(); k++) {\n        const t = tileAt(this.c, this.tile, j.index + k);\n        const n = tileChunkCount(t);\n        if (k > 0 && this.batchChunks + n > this.budget) break;\n        const err = this.backend.add(k,\n          { x: t.cx0 * 16, y: this.y, z: t.cz0 * 16 },\n          { x: t.cx1 * 16 + 15, y: this.y, z: t.cz1 * 16 + 15 });\n        if (err) { firstErr = err; break; }\n        const probes = [];\n        for (let cx = t.cx0; cx <= t.cx1; cx++)\n          for (let cz = t.cz0; cz <= t.cz1; cz++) probes.push(cx * 16 + 8, cz * 16 + 8);\n        this.tiles.push({ k, n, probes, done: false, t });\n        this.batchChunks += n;\n      }\n      if (!this.tiles.length) {\n        this.error = `Couldn't create a ticking area via ${this.backend.label}: ${firstErr}`;\n        return \"paused\";\n      }\n      this.state = \"wait\";\n      this.since = now;\n      this.loadedAt = null;\n      return \"running\";\n    }\n\n    // wait: a tile is done when the backend says so or every chunk probe answers\n    let open = 0;\n    for (const t of this.tiles) {\n      if (t.done) continue;\n      if (this.backend.loaded(t.k)) { t.done = true; continue; }\n      const next = [];\n      for (let i = 0; i < t.probes.length; i += 2)\n        if (!isLoadedAt(this.dim, t.probes[i], t.probes[i + 1], this.y)) next.push(t.probes[i], t.probes[i + 1]);\n      t.probes = next;\n      if (next.length) open++; else t.done = true;\n    }\n\n    if (!open) {\n      if (this.loadedAt === null) this.loadedAt = now;\n      if (now - this.loadedAt >= j.opts.settle) this.finishBatch();\n    } else if (now - this.since >= j.opts.timeout) {\n      this.finishBatch();\n    }\n    return \"running\";\n  }\n\n  finishBatch() {\n    const j = this.job;\n    let skipped = 0;\n    for (const t of this.tiles) {\n      if (!t.done) skipped += t.probes.length / 2;\n      // mark while still loaded, so Bedrock saves the chunks instead of dropping them\n      if (j.opts.mark !== false) {\n        const m = markRect(this.dim, t.t.cx0, t.t.cz0, t.t.cx1, t.t.cz1, this.markY);\n        j.marked = (j.marked || 0) + m.ok;\n        j.markMissed = (j.markMissed || 0) + m.missed;\n      }\n      this.backend.remove(t.k);\n    }\n    j.index += this.tiles.length;\n    j.done += this.batchChunks - skipped;\n    j.skipped += skipped;\n    saveJob(j);\n    this.state = \"place\";\n  }\n\n  suspend() { this.backend.clear(); }\n  cleanup() { this.backend.clear(); }\n}\n","scripts/chunks.js":"// A chunk is \"loaded\" (and therefore generated) when the server can return a block in it.\nexport function probeY(dim) {\n  try {\n    const h = dim.heightRange;\n    return Math.max(h.min, Math.min(64, h.max - 1));\n  } catch {\n    return 64;\n  }\n}\n\nexport function isLoadedAt(dim, x, z, y) {\n  try {\n    return dim.getBlock({ x, y, z }) !== undefined;\n  } catch {\n    return false;\n  }\n}\n","scripts/cmd.js":"// Command wrapper: returns successCount, treating any throw as failure.\nexport function runCmd(target, command) {\n  try {\n    const r = target.runCommand(command);\n    return r?.successCount ?? 0;\n  } catch {\n    return 0;\n  }\n}\n","scripts/commands.js":"import * as runner from \"./runner.js\";\nimport { buildJob, parseArgs, parseCoord, toInt } from \"./jobs.js\";\nimport { normRect } from \"./geometry.js\";\nimport { say } from \"./log.js\";\nimport { openMenu } from \"./ui.js\";\nimport { runDiag } from \"./diag.js\";\n\nconst HELP = [\n  \"§bChunk Pregen§r commands (all via /scriptevent):\",\n  \"pregen:menu  form UI\",\n  \"pregen:area <x1> <z1> <x2> <z2> [dim=overworld|nether|end] [budget=1000] [timeout=60]\",\n  \"pregen:walk <x1> <z1> <x2> <z2> [step=128] [y=200] [gm=spectator|creative] [maxdwell=20]\",\n  \"pregen:radius <area|walk> <blocks> [cx= cz=] [same options]\",\n  \"pregen:status | pause | resume | stop | diag\",\n  \"Coordinates accept ~ and ~N. mark=off skips the save marker. pregen:diag tests ticking-area creation.\",\n].join(\"\\n\");\n\nexport function handleScriptEvent(ev) {\n  const sub = String(ev.id).split(\":\")[1]?.toLowerCase();\n  const src = ev.sourceEntity;\n  const player = src?.typeId === \"minecraft:player\" ? src : undefined;\n  try {\n    run(sub, parseArgs(ev.message), player, src);\n  } catch (e) {\n    say(`§c${e?.message ?? e}`, player);\n  }\n}\n\nfunction run(sub, { pos, opts }, player, src) {\n  const loc = src?.location;\n  const srcDim = src?.dimension?.id;\n\n  switch (sub) {\n    case \"area\":\n    case \"walk\": {\n      if (pos.length < 4) throw new Error(`Usage: /scriptevent pregen:${sub} <x1> <z1> <x2> <z2> [options]`);\n      const rect = normRect(\n        parseCoord(pos[0], loc?.x, \"x1\"), parseCoord(pos[1], loc?.z, \"z1\"),\n        parseCoord(pos[2], loc?.x, \"x2\"), parseCoord(pos[3], loc?.z, \"z2\"));\n      runner.start(buildJob(sub, rect, opts, player, srcDim), player);\n      return;\n    }\n    case \"radius\": {\n      const mode = String(pos[0] ?? \"\").toLowerCase();\n      if (mode !== \"area\" && mode !== \"walk\") throw new Error(\"Usage: /scriptevent pregen:radius <area|walk> <blocks>\");\n      const r = toInt(pos[1], \"radius\");\n      if (r <= 0) throw new Error(\"radius must be positive\");\n      const cx = opts.cx !== undefined ? toInt(opts.cx, \"cx\") : loc ? Math.floor(loc.x) : undefined;\n      const cz = opts.cz !== undefined ? toInt(opts.cz, \"cz\") : loc ? Math.floor(loc.z) : undefined;\n      if (cx === undefined || cz === undefined) throw new Error(\"No position to center on; pass cx= and cz=\");\n      runner.start(buildJob(mode, normRect(cx - r, cz - r, cx + r, cz + r), opts, player, srcDim), player);\n      return;\n    }\n    case \"status\": say(runner.statusText(), player); return;\n    case \"pause\": runner.pause(\"paused by command\", player); return;\n    case \"resume\": runner.resume(player); return;\n    case \"stop\": runner.stop({ player }); return;\n    case \"diag\": runDiag(player, srcDim); return;\n    case \"menu\":\n      if (!player) throw new Error(\"The menu must be opened by a player\");\n      openMenu(player);\n      return;\n    default: say(HELP, player);\n  }\n}\n","scripts/diag.js":"// /scriptevent pregen:diag: reports which ticking-area backend is active and tries a 1-chunk test area.\nimport { world } from \"@minecraft/server\";\nimport { getManager, makeBackend, backendName, errText } from \"./areaMode.js\";\nimport { probeY } from \"./chunks.js\";\nimport { say } from \"./log.js\";\n\nexport function runDiag(player, srcDimId) {\n  const dim = player?.dimension ?? world.getDimension(srcDimId ?? \"minecraft:overworld\");\n  const lines = [`Ticking-area backend: ${backendName()}`];\n  const tam = getManager();\n  if (tam) {\n    try { lines.push(`Pack chunk budget: ${tam.chunkCount} in use of ${tam.maxChunkCount}`); }\n    catch (e) { lines.push(`Budget unreadable: ${errText(e)}`); }\n  }\n  const loc = player?.location ?? { x: 0, z: 0 };\n  const x = Math.floor(loc.x / 16) * 16, z = Math.floor(loc.z / 16) * 16, y = probeY(dim);\n  const b = makeBackend(dim);\n  b.beginBatch();\n  const err = b.add(\"diag\", { x, y, z }, { x: x + 15, y, z: z + 15 });\n  lines.push(err ? `Test area: §cFAILED§r: ${err}` : \"Test area: §acreated OK§r (removed again)\");\n  b.remove(\"diag\");\n  say(lines.join(\"\\n\"), player);\n}\n","scripts/geometry.js":"// Pure chunk/tile/path math. No game API here so it can be tested headless.\nexport const CHUNK = 16;\nexport const toChunk = (v) => Math.floor(v / CHUNK);\n\nexport function normRect(x1, z1, x2, z2) {\n  return {\n    x0: Math.min(x1, x2), z0: Math.min(z1, z2),\n    x1: Math.max(x1, x2), z1: Math.max(z1, z2),\n  };\n}\n\nexport function chunkRect(r) {\n  return { cx0: toChunk(r.x0), cz0: toChunk(r.z0), cx1: toChunk(r.x1), cz1: toChunk(r.z1) };\n}\n\nexport function chunkCount(c) {\n  return (c.cx1 - c.cx0 + 1) * (c.cz1 - c.cz0 + 1);\n}\n\n// Tiles of up to tile x tile chunks (ticking areas are capped at 100 chunks).\nexport function tileGrid(c, tile) {\n  const cols = Math.ceil((c.cx1 - c.cx0 + 1) / tile);\n  const rows = Math.ceil((c.cz1 - c.cz0 + 1) / tile);\n  return { cols, rows, total: cols * rows };\n}\n\n// Serpentine order, computed by index so huge regions never need a stored list.\nexport function tileAt(c, tile, i) {\n  const { cols } = tileGrid(c, tile);\n  const row = Math.floor(i / cols);\n  let col = i % cols;\n  if (row & 1) col = cols - 1 - col;\n  const cx0 = c.cx0 + col * tile;\n  const cz0 = c.cz0 + row * tile;\n  return { cx0, cz0, cx1: Math.min(cx0 + tile - 1, c.cx1), cz1: Math.min(cz0 + tile - 1, c.cz1) };\n}\n\nexport function tileChunkCount(t) {\n  return (t.cx1 - t.cx0 + 1) * (t.cz1 - t.cz0 + 1);\n}\n\n// Walk path: one stop per step x step block cell, serpentine.\nexport function walkGrid(r, step) {\n  const nx = Math.max(1, Math.ceil((r.x1 - r.x0 + 1) / step));\n  const nz = Math.max(1, Math.ceil((r.z1 - r.z0 + 1) / step));\n  return { nx, nz, total: nx * nz };\n}\n\nexport function walkPointAt(r, step, i) {\n  const { nx } = walkGrid(r, step);\n  const row = Math.floor(i / nx);\n  let col = i % nx;\n  if (row & 1) col = nx - 1 - col;\n  return {\n    x: Math.min(r.x0 + Math.floor(step * (col + 0.5)), r.x1),\n    z: Math.min(r.z0 + Math.floor(step * (row + 0.5)), r.z1),\n  };\n}\n","scripts/jobs.js":"// Argument parsing and job construction shared by chat commands and the form UI.\nimport { chunkRect, chunkCount, walkGrid } from \"./geometry.js\";\nimport { captureRestore } from \"./restore.js\";\n\nconst DIMS = {\n  overworld: \"minecraft:overworld\",\n  nether: \"minecraft:nether\",\n  end: \"minecraft:the_end\",\n  the_end: \"minecraft:the_end\",\n};\n\nexport function resolveDim(v) {\n  if (v === undefined) return undefined;\n  const k = String(v).toLowerCase().replace(/^minecraft:/, \"\");\n  if (!DIMS[k]) throw new Error(`Unknown dimension \"${v}\" (use overworld, nether or end)`);\n  return DIMS[k];\n}\n\nexport function toInt(v, name = \"value\") {\n  const n = Number(v);\n  if (v === \"\" || v === undefined || !Number.isFinite(n)) throw new Error(`${name}: \"${v}\" is not a number`);\n  return Math.floor(n);\n}\n\n// Accepts absolute numbers, \"~\" and \"~N\" relative to base.\nexport function parseCoord(v, base, name) {\n  if (v === undefined || v === \"\") throw new Error(`Missing ${name}`);\n  if (v.startsWith(\"~\")) {\n    if (base === undefined) throw new Error(`\"~\" needs a player to be relative to`);\n    const rest = v.slice(1);\n    return Math.floor(base) + (rest ? toInt(rest, name) : 0);\n  }\n  return toInt(v, name);\n}\n\nfunction intOpt(o, key, def, min, max) {\n  if (o[key] === undefined) return def;\n  const n = toInt(o[key], key);\n  if (n < min || n > max) throw new Error(`${key} must be between ${min} and ${max}`);\n  return n;\n}\n\nfunction secOpt(o, key, defSec, min, max) {\n  if (o[key] === undefined) return Math.round(defSec * 20);\n  const n = Number(o[key]);\n  if (!Number.isFinite(n) || n < min || n > max) throw new Error(`${key} must be ${min}–${max} seconds`);\n  return Math.round(n * 20);\n}\n\nexport function parseArgs(message) {\n  const pos = [];\n  const opts = {};\n  for (const tok of String(message ?? \"\").trim().split(/\\s+/).filter(Boolean)) {\n    const eq = tok.indexOf(\"=\");\n    if (eq > 0) opts[tok.slice(0, eq).toLowerCase()] = tok.slice(eq + 1);\n    else pos.push(tok);\n  }\n  return { pos, opts };\n}\n\nfunction boolOpt(o, key, def) {\n  if (o[key] === undefined) return def;\n  const v = String(o[key]).toLowerCase();\n  if ([\"on\", \"true\", \"1\", \"yes\"].includes(v)) return true;\n  if ([\"off\", \"false\", \"0\", \"no\"].includes(v)) return false;\n  throw new Error(`${key} must be on or off`);\n}\n\nexport function buildJob(mode, rect, o, player, fallbackDim) {\n  const mark = boolOpt(o, \"mark\", true);\n  const base = { mode, rect, index: 0, done: 0, skipped: 0, activeTicks: 0, paused: true, pauseReason: \"new\" };\n\n  if (mode === \"area\") {\n    const dim = resolveDim(o.dim) ?? fallbackDim ?? \"minecraft:overworld\";\n    const opts = {\n      tile: intOpt(o, \"tile\", 10, 1, 32),\n      budget: intOpt(o, \"budget\", 1000, 1, 20000),\n      timeout: secOpt(o, \"timeout\", 60, 5, 600),\n      settle: secOpt(o, \"settle\", 1, 0, 30),\n      mark,\n    };\n    return { ...base, dim, opts, total: chunkCount(chunkRect(rect)) };\n  }\n\n  if (mode === \"walk\") {\n    if (!player) throw new Error(\"Walk mode must be started by a player (run the command from chat)\");\n    const gm = String(o.gm ?? o.gamemode ?? \"spectator\").toLowerCase();\n    if (gm !== \"spectator\" && gm !== \"creative\") throw new Error(\"gm must be spectator or creative\");\n    const dim = resolveDim(o.dim) ?? player.dimension.id;\n    const opts = {\n      step: intOpt(o, \"step\", 128, 16, 512),\n      y: o.y === undefined ? null : intOpt(o, \"y\", 200, -64, 319),\n      gamemode: gm,\n      minDwell: secOpt(o, \"dwell\", 0.5, 0, 30),\n      maxDwell: secOpt(o, \"maxdwell\", 20, 2, 300),\n      mark,\n    };\n    return {\n      ...base, dim, opts,\n      total: walkGrid(rect, opts.step).total,\n      playerId: player.id, playerName: player.name,\n      restore: captureRestore(player),\n    };\n  }\n\n  throw new Error(`Unknown mode \"${mode}\" (use area or walk)`);\n}\n","scripts/log.js":"import { world } from \"@minecraft/server\";\n\nconst PREFIX = \"§b[pregen]§r \";\n\nexport function say(msg, target) {\n  try { (target ?? world).sendMessage(PREFIX + msg); } catch { /* player gone */ }\n}\n\nexport function actionBar(text) {\n  for (const p of world.getAllPlayers()) {\n    try { p.onScreenDisplay.setActionBar(text); } catch { /* ignore */ }\n  }\n}\n\nexport function fmtDuration(sec) {\n  if (!Number.isFinite(sec) || sec < 0) return \"—\";\n  sec = Math.round(sec);\n  const h = Math.floor(sec / 3600);\n  const m = Math.floor((sec % 3600) / 60);\n  const s = sec % 60;\n  if (h) return `${h}h${String(m).padStart(2, \"0\")}m`;\n  if (m) return `${m}m${String(s).padStart(2, \"0\")}s`;\n  return `${s}s`;\n}\n","scripts/main.js":"// Chunk Pregen v1.0.0: entry point. Wires events and the job tick loop.\nimport { world, system } from \"@minecraft/server\";\nimport { handleScriptEvent } from \"./commands.js\";\nimport * as runner from \"./runner.js\";\nimport { applyDeferredRestore } from \"./restore.js\";\n\nsystem.afterEvents.scriptEventReceive.subscribe((ev) => {\n  try { handleScriptEvent(ev); } catch (e) { console.warn(`[pregen] ${e}`); }\n}, { namespaces: [\"pregen\"] });\n\nlet booted = false;\nfunction boot() {\n  if (booted) return;\n  booted = true;\n  runner.init();\n  system.runInterval(() => runner.tick(system.currentTick), runner.TICK_INTERVAL);\n}\n\n// Script API 2.x runs in early-execution mode: touch the world only after it has loaded.\nif (world.afterEvents.worldLoad) world.afterEvents.worldLoad.subscribe(boot);\nelse system.run(boot);\n\nworld.afterEvents.playerSpawn.subscribe((ev) => {\n  if (!ev.initialSpawn) return;\n  const player = ev.player;\n  system.runTimeout(() => {\n    try {\n      applyDeferredRestore(player);\n      runner.notifySpawn(player);\n    } catch { /* player left again */ }\n  }, 40);\n});\n","scripts/mark.js":"// Bedrock only writes a chunk to disk if it changed since generation; an\n// untouched chunk is thrown away and regenerated from the seed next time.\n// To make a pre-generated chunk persist, flip one block and put it back:\n// the chunk is now \"modified\" and gets saved, and the world is unchanged.\n//\n// The block used is at the top of the world, above anything natural:\n// air at the build limit in the Overworld and End (flipped via structure_void),\n// bedrock roof in the Nether (flipped via barrier; both are indestructible).\nexport function markY(dim) {\n  try { return dim.heightRange.max - 1; } catch { return 319; }\n}\n\nconst FLIP = {\n  \"minecraft:air\": \"minecraft:structure_void\",\n  \"minecraft:bedrock\": \"minecraft:barrier\",\n};\n\n// returns \"ok\" | \"unloaded\" | \"occupied\" | \"error\"\nexport function markChunk(dim, cx, cz, y) {\n  let b;\n  try { b = dim.getBlock({ x: cx * 16 + 8, y, z: cz * 16 + 8 }); } catch { return \"unloaded\"; }\n  if (!b) return \"unloaded\";\n  try {\n    const id = b.typeId;\n    const tmp = FLIP[id];\n    if (!tmp) return \"occupied\";            // something built at the top: the chunk is modified anyway\n    b.setType(tmp);\n    b.setType(id);\n    return \"ok\";\n  } catch {\n    return \"error\";\n  }\n}\n\n// mark every chunk in a chunk rectangle; returns { ok, missed }\nexport function markRect(dim, cx0, cz0, cx1, cz1, y) {\n  let ok = 0, missed = 0;\n  for (let cx = cx0; cx <= cx1; cx++)\n    for (let cz = cz0; cz <= cz1; cz++) {\n      const r = markChunk(dim, cx, cz, y);\n      if (r === \"ok\" || r === \"occupied\") ok++; else missed++;\n    }\n  return { ok, missed };\n}\n","scripts/restore.js":"// Remembers where a walking player started so they can be put back afterwards,\n// even if they were offline when the job ended.\nimport { world } from \"@minecraft/server\";\nimport { runCmd } from \"./cmd.js\";\n\nconst KEY = \"pregen:restore\";\nconst MODES = [\"survival\", \"creative\", \"adventure\", \"spectator\"];\n\nexport function captureRestore(player) {\n  const l = player.location;\n  let gm = \"survival\";\n  try { gm = String(player.getGameMode()).toLowerCase(); } catch { /* keep default */ }\n  return {\n    name: player.name,\n    x: l.x, y: l.y, z: l.z,\n    dim: player.dimension.id,\n    gm: MODES.includes(gm) ? gm : \"survival\",\n  };\n}\n\nexport function applyRestore(player, r) {\n  if (!r) return;\n  try { player.teleport({ x: r.x, y: r.y, z: r.z }, { dimension: world.getDimension(r.dim) }); } catch { /* ignore */ }\n  runCmd(player, `gamemode ${r.gm} @s`);\n}\n\nexport function deferRestore(r) {\n  if (!r) return;\n  try { world.setDynamicProperty(KEY, JSON.stringify(r)); } catch { /* ignore */ }\n}\n\nexport function applyDeferredRestore(player) {\n  try {\n    const s = world.getDynamicProperty(KEY);\n    if (typeof s !== \"string\") return false;\n    const r = JSON.parse(s);\n    if (r.name !== player.name) return false;\n    applyRestore(player, r);\n    world.setDynamicProperty(KEY, undefined);\n    return true;\n  } catch {\n    return false;\n  }\n}\n","scripts/runner.js":"// Owns the single active job: start/pause/resume/stop, per-tick driving, progress display.\nimport { world } from \"@minecraft/server\";\nimport { AreaRunner, clearAreas, finalizeArea, backendName } from \"./areaMode.js\";\nimport { WalkRunner, finalizeWalk } from \"./walkMode.js\";\nimport { loadJob, saveJob } from \"./store.js\";\nimport { say, actionBar, fmtDuration } from \"./log.js\";\n\nexport const TICK_INTERVAL = 5;\nconst BAR_EVERY = 20;\n\nlet job = null;\nlet active = null;\nlet rate = null;\nlet lastBar = -Infinity;\n\nconst unit = (j) => (j.mode === \"area\" ? \"chunks\" : \"stops\");\nconst processed = (j) => j.done + j.skipped;\nconst pct = (j) => (j.total ? Math.floor((processed(j) / j.total) * 100) : 100);\nconst dimName = (id) => id.replace(\"minecraft:\", \"\").replace(\"the_end\", \"end\");\n\nexport function getJob() { return job; }\n\nexport function init() {\n  job = loadJob();\n  if (!job) return;\n  if (!job.paused) {\n    job.paused = true;\n    job.pauseReason = \"the world was closed\";\n    saveJob(job);\n  }\n  if (job.mode === \"area\") {\n    try { clearAreas(world.getDimension(job.dim)); } catch { /* ignore */ }\n  }\n}\n\nfunction rateInfo(now) {\n  if (!rate || now - rate.t <= 0) return { perSec: NaN, eta: NaN };\n  const perSec = (processed(job) - rate.d) / ((now - rate.t) / 20);\n  return { perSec, eta: perSec > 0 ? (job.total - processed(job)) / perSec : NaN };\n}\n\nexport function statusText(now, withPause = true) {\n  if (!job) return \"No pregen job.\";\n  const j = job;\n  let s = `${j.mode} in ${dimName(j.dim)}: ${processed(j)}/${j.total} ${unit(j)} (${pct(j)}%)`;\n  if (j.skipped) s += `, ${j.skipped} timed out`;\n  if (j.opts.mark !== false && j.marked) s += `, ${j.marked} marked`;\n  s += `, active ${fmtDuration(j.activeTicks / 20)}`;\n  if (j.paused) { if (withPause) s += `. §ePaused§r (${j.pauseReason})`; }\n  else if (now !== undefined) {\n    const r = rateInfo(now);\n    if (Number.isFinite(r.perSec)) s += `. ${r.perSec.toFixed(1)} ${unit(j)}/s, ETA ${fmtDuration(r.eta)}`;\n  }\n  return s;\n}\n\nfunction startMessage(j) {\n  const r = j.rect;\n  const region = `${r.x0},${r.z0} → ${r.x1},${r.z1} in ${dimName(j.dim)}`;\n  if (j.mode === \"area\") {\n    return `Area pregen: ${j.total} chunks (${region}) using ${backendName()}. Progress on the action bar.`;\n  }\n  return `Walk pregen: ${j.total} stops every ${j.opts.step} blocks (${region}) in ${j.opts.gamemode}. ` +\n    `You'll be returned to your start point when it finishes or you stop it.`;\n}\n\nexport function start(newJob, player) {\n  if (job) stop({ silent: true });\n  job = newJob;\n  saveJob(job);\n  say(startMessage(job), player);\n  resume(player, true);\n}\n\nexport function resume(player, fresh = false) {\n  if (!job) { say(\"No job to resume.\", player); return; }\n  if (!job.paused && active) { say(\"Already running.\", player); return; }\n  const r = job.mode === \"area\" ? new AreaRunner(job) : new WalkRunner(job);\n  const err = r.start();\n  if (err) {\n    job.paused = true;\n    job.pauseReason = err;\n    saveJob(job);\n    say(`§c${err}`, player);\n    return;\n  }\n  if (r.notice) say(r.notice, player);\n  active = r;\n  job.paused = false;\n  job.pauseReason = null;\n  saveJob(job);\n  rate = null;\n  if (!fresh) say(`Resumed. ${statusText()}`, player);\n}\n\nexport function pause(reason, player) {\n  if (!job) { say(\"No job running.\", player); return; }\n  if (job.paused) { say(\"Already paused.\", player); return; }\n  try { active?.suspend(); } catch { /* ignore */ }\n  active = null;\n  job.paused = true;\n  job.pauseReason = reason;\n  saveJob(job);\n  say(`§ePaused:§r ${reason}\\nProgress: ${statusText(undefined, false)}. /scriptevent pregen:resume to continue.`, player);\n}\n\nexport function stop({ silent = false, player } = {}) {\n  if (!job) { if (!silent) say(\"No job to stop.\", player); return; }\n  const j = job;\n  try {\n    if (active) active.cleanup();\n    else if (j.mode === \"area\") finalizeArea(j);\n    else finalizeWalk(j);\n  } catch { /* ignore */ }\n  active = null;\n  job = null;\n  saveJob(null);\n  if (!silent) say(`Stopped at ${processed(j)}/${j.total} ${unit(j)}. Ticking areas removed${j.mode === \"walk\" ? \", player restored\" : \"\"}.`, player);\n}\n\nfunction finish() {\n  const j = job;\n  try { active.cleanup(); } catch { /* ignore */ }\n  active = null;\n  job = null;\n  saveJob(null);\n  let msg = `§aDone.§r ${j.done} ${unit(j)} completed in ${fmtDuration(j.activeTicks / 20)}`;\n  if (j.opts.mark !== false) {\n    msg += `, ${j.marked || 0} chunks marked so Bedrock saves them`;\n    if (j.markMissed) msg += ` (${j.markMissed} could not be marked)`;\n  }\n  if (j.skipped) {\n    msg += `, ${j.skipped} timed out`;\n    if (j.mode === \"walk\") msg += \" (raise render distance or lower step=)\";\n    else msg += \" (rerun the same region to catch them; loaded chunks go fast)\";\n  }\n  say(msg + \".\");\n  actionBar(\"§aPregen complete\");\n}\n\nexport function tick(now) {\n  if (!job || job.paused || !active) return;\n  job.activeTicks += TICK_INTERVAL;\n  if (!rate) rate = { t: now, d: processed(job) };\n\n  let result;\n  try {\n    result = active.tick(now);\n  } catch (e) {\n    active.error = `script error: ${e}`;\n    result = \"paused\";\n  }\n\n  if (result === \"done\") finish();\n  else if (result === \"paused\") pause(active?.error ?? \"stopped\");\n  else if (now - lastBar >= BAR_EVERY) {\n    lastBar = now;\n    const r = rateInfo(now);\n    const rs = Number.isFinite(r.perSec) ? ` · ${r.perSec.toFixed(1)}/s · ETA ${fmtDuration(r.eta)}` : \"\";\n    actionBar(`§bPregen§r ${pct(job)}% · ${processed(job)}/${job.total} ${unit(job)}${rs}`);\n  }\n}\n\nexport function notifySpawn(player) {\n  if (job && job.paused) {\n    say(`A pregen job is paused at ${pct(job)}% (${job.pauseReason}). ` +\n      `/scriptevent pregen:resume or pregen:stop`, player);\n  }\n}\n","scripts/store.js":"import { world } from \"@minecraft/server\";\n\nconst JOB_KEY = \"pregen:job\";\n\nexport function loadJob() {\n  try {\n    const s = world.getDynamicProperty(JOB_KEY);\n    return typeof s === \"string\" ? JSON.parse(s) : null;\n  } catch {\n    return null;\n  }\n}\n\nexport function saveJob(job) {\n  try {\n    world.setDynamicProperty(JOB_KEY, job ? JSON.stringify(job) : undefined);\n  } catch (e) {\n    console.warn(`[pregen] could not save job: ${e}`);\n  }\n}\n","scripts/ui.js":"// Form UI: /scriptevent pregen:menu. Uses only form signatures shared by server-ui 1.x and 2.x.\nimport { system } from \"@minecraft/server\";\nimport { ActionFormData, ModalFormData } from \"@minecraft/server-ui\";\nimport * as runner from \"./runner.js\";\nimport { buildJob, parseCoord, toInt } from \"./jobs.js\";\nimport { normRect } from \"./geometry.js\";\nimport { say } from \"./log.js\";\n\nconst wait = (t) => new Promise((res) => system.runTimeout(res, t));\n\n// Chat is still open right after typing the command; retry until the player can see the form.\nasync function show(player, form) {\n  for (let i = 0; i < 60; i++) {\n    const res = await form.show(player);\n    if (res.canceled && res.cancelationReason === \"UserBusy\") { await wait(10); continue; }\n    return res;\n  }\n  return { canceled: true };\n}\n\nexport function openMenu(player) {\n  if (!player) return;\n  const p = runner.getJob() ? jobMenu(player) : newJobMenu(player);\n  p.catch((e) => say(`§c${e?.message ?? e}`, player));\n}\n\nasync function jobMenu(player) {\n  const j = runner.getJob();\n  const form = new ActionFormData()\n    .title(\"Chunk Pregen\")\n    .body(runner.statusText())\n    .button(j.paused ? \"Resume\" : \"Pause\")\n    .button(\"Stop and clean up\")\n    .button(\"Close\");\n  const r = await show(player, form);\n  if (r.canceled) return;\n  if (r.selection === 0) {\n    if (runner.getJob()?.paused) runner.resume(player);\n    else runner.pause(\"paused from menu\", player);\n  } else if (r.selection === 1) {\n    runner.stop({ player });\n  }\n}\n\nfunction corner(text, player, label) {\n  const parts = String(text ?? \"\").trim().split(/[\\s,]+/).filter(Boolean);\n  if (parts.length !== 2) throw new Error(`${label}: enter \"X Z\", e.g. -1000 500`);\n  return [parseCoord(parts[0], player.location.x, `${label} X`), parseCoord(parts[1], player.location.z, `${label} Z`)];\n}\n\nasync function newJobMenu(player) {\n  const form = new ModalFormData()\n    .title(\"Chunk Pregen\")\n    .dropdown(\"Mode\", [\"Area: ticking areas, fastest\", \"Walk: teleports you, fills held maps\"])\n    .dropdown(\"Region\", [\"Square around me (radius)\", \"Two corners\"])\n    .textField(\"Radius in blocks\", \"e.g. 1000\")\n    .textField(\"Corner 1: X Z  (~ works)\", \"e.g. -1000 -1000\")\n    .textField(\"Corner 2: X Z\", \"e.g. 1000 1000\")\n    .textField(\"Walk step in blocks (blank = 128)\", \"64 for dense map fill\")\n    .toggle(\"Walk in creative instead of spectator\");\n  const r = await show(player, form);\n  if (r.canceled) return;\n\n  const [modeI, regionI, radius, c1, c2, step, creative] = r.formValues;\n  const mode = modeI === 1 ? \"walk\" : \"area\";\n\n  let rect;\n  if (regionI === 0) {\n    const rad = toInt(String(radius).trim(), \"Radius\");\n    if (rad <= 0) throw new Error(\"Radius must be positive\");\n    const cx = Math.floor(player.location.x), cz = Math.floor(player.location.z);\n    rect = normRect(cx - rad, cz - rad, cx + rad, cz + rad);\n  } else {\n    const [x1, z1] = corner(c1, player, \"Corner 1\");\n    const [x2, z2] = corner(c2, player, \"Corner 2\");\n    rect = normRect(x1, z1, x2, z2);\n  }\n\n  const opts = {};\n  if (mode === \"walk\") {\n    if (String(step ?? \"\").trim()) opts.step = String(step).trim();\n    opts.gm = creative ? \"creative\" : \"spectator\";\n  }\n  runner.start(buildJob(mode, rect, opts, player, player.dimension.id), player);\n}\n","scripts/walkMode.js":"// WALK mode: teleport the player along a serpentine grid and wait at each stop until\n// the surrounding chunks are loaded. Slower than AREA, but maps held by the player fill in.\nimport { world } from \"@minecraft/server\";\nimport { walkGrid, walkPointAt } from \"./geometry.js\";\nimport { isLoadedAt, probeY } from \"./chunks.js\";\nimport { runCmd } from \"./cmd.js\";\nimport { saveJob } from \"./store.js\";\nimport { applyRestore, deferRestore } from \"./restore.js\";\nimport { markRect, markY } from \"./mark.js\";\nimport { toChunk } from \"./geometry.js\";\n\nexport function findPlayer(job) {\n  const ps = world.getAllPlayers();\n  return ps.find((p) => p.id === job.playerId) ?? ps.find((p) => p.name === job.playerName);\n}\n\nexport function defaultWalkY(dim) {\n  try { return Math.min(200, dim.heightRange.max - 8); } catch { return 200; }\n}\n\nexport function finalizeWalk(job) {\n  const p = findPlayer(job);\n  if (p) applyRestore(p, job.restore);\n  else deferRestore(job.restore);\n}\n\nexport class WalkRunner {\n  constructor(job) {\n    this.job = job;\n    this.dim = world.getDimension(job.dim);\n    this.grid = walkGrid(job.rect, job.opts.step);\n    this.y = job.opts.y ?? defaultWalkY(this.dim);\n    this.py = probeY(this.dim);\n    this.markY = markY(this.dim);\n    this.state = \"move\";\n    this.error = null;\n  }\n\n  start() {\n    const p = findPlayer(this.job);\n    if (!p) return `${this.job.playerName} is not online`;\n    runCmd(p, `gamemode ${this.job.opts.gamemode} @s`);\n    return null;\n  }\n\n  tp(p) {\n    try {\n      p.teleport({ x: this.pt.x + 0.5, y: this.y, z: this.pt.z + 0.5 }, { dimension: this.dim });\n    } catch { /* retried next tick */ }\n  }\n\n  tick(now) {\n    const j = this.job;\n    const p = findPlayer(j);\n    if (!p) { this.error = `${j.playerName} left the world`; return \"paused\"; }\n\n    if (this.state === \"move\") {\n      if (j.index >= this.grid.total) return \"done\";\n      this.pt = walkPointAt(j.rect, j.opts.step, j.index);\n      this.tp(p);\n      this.since = now;\n      this.state = \"wait\";\n      return \"running\";\n    }\n\n    const el = now - this.since;\n    if (j.opts.gamemode !== \"spectator\") this.tp(p); // creative players fall; hold altitude\n    if (el < j.opts.minDwell) return \"running\";\n\n    const h = Math.floor(j.opts.step / 2);\n    const { x, z } = this.pt;\n    const ok = [[0, 0], [-h, -h], [h, -h], [-h, h], [h, h]]\n      .every(([dx, dz]) => isLoadedAt(this.dim, x + dx, z + dz, this.py));\n\n    if (ok || el >= j.opts.maxDwell) {\n      if (ok) j.done++; else j.skipped++;\n      // mark this stop's chunks (clipped to the region) so Bedrock saves them\n      if (j.opts.mark !== false) {\n        const r = j.rect;\n        const m = markRect(this.dim,\n          Math.max(toChunk(x - h), toChunk(r.x0)), Math.max(toChunk(z - h), toChunk(r.z0)),\n          Math.min(toChunk(x + h - 1), toChunk(r.x1)), Math.min(toChunk(z + h - 1), toChunk(r.z1)), this.markY);\n        j.marked = (j.marked || 0) + m.ok;\n        j.markMissed = (j.markMissed || 0) + m.missed;\n      }\n      j.index++;\n      saveJob(j);\n      this.state = \"move\";\n    }\n    return \"running\";\n  }\n\n  suspend() { /* leave the player where they are */ }\n  cleanup() { finalizeWalk(this.job); }\n}\n"};
export const PREGEN_BINARY = {"pack_icon.png":""};
